.track-add {
  color: var(--plum);
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: repeating-linear-gradient(to bottom, var(--line) 0 1px, transparent 1px calc(var(--slot) / 2 - 1px), #eae2db90 calc(var(--slot) / 2 - 1px) calc(var(--slot) / 2), transparent calc(var(--slot) / 2) var(--slot));
}
.track-add:focus-visible { outline-offset: -3px; z-index: 1; }
.slot-hint { position: absolute; inset: 0 1px auto; top: var(--hint-top, 0%); height: calc(var(--slot) / 2); border-radius: 4px; display: none; place-items: center; background: #ead8e9a8; pointer-events: none; }
