.booking { position: absolute; top: calc(var(--top) + 1px); height: calc(var(--height) - 2px); left: 2px; right: 2px; text-align: left; border: 1px solid var(--edge); border-left: 3px solid var(--accent); background: var(--tint); border-radius: 5px; padding: 4px 3px; color: var(--group-ink); display: flex; flex-direction: column; justify-content: center; align-items: flex-start; overflow: hidden; }
