.progress { height: 4px; border-radius: 9px; background: #eee6e9; margin-top: 13px; overflow: hidden; }
.progress span { display: block; height: 100%; width: var(--progress, 0%); background: var(--plum); }
.group-list { display: grid; gap: 8px; padding: 0 12px 12px; }
.group-card { min-height: 78px; display: flex; width: 100%; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 8px; padding: 8px; text-align: left; background: var(--surface); }
.group-card:hover { background: var(--tint); border-color: var(--edge); }
.group-mark { flex: none; display: grid; place-items: center; width: 31px; height: 34px; border-radius: 6px; background: var(--tint); color: var(--group-ink); font: 18px var(--serif); border: 1px solid var(--edge); }
.group-copy { min-width: 0; flex: 1; }
.group-name { display: block; font-size: 14px; font-weight: 740; }
