.duet { --group-ink: #264d44; --tint: #e6f0e9; --edge: #c8e0d2; --accent: #47806d; }
.movement { --group-ink: #684916; --tint: #f8edda; --edge: #ecd8af; --accent: #a5732c; }
.readers { --group-ink: #463d6a; --tint: #ede9f6; --edge: #ddd3ef; --accent: #7967a6; }
.feedback { grid-column: 1 / -1; color: var(--plum); font-size: 13px; min-height: 19px; }
.workspace:has(.feedback:empty) { row-gap: 0; }

dialog { width: min(470px, calc(100% - 24px)); max-height: calc(100% - 24px); margin: auto; border: 1px solid var(--line); border-radius: 14px; padding: 20px; background: var(--surface); color: var(--ink); box-shadow: 0 12px 60px #23172042; }
